import { expect, test, type Page, type Route } from '@playwright/test'

test.describe.configure({ timeout: 45_000 })

/** Model that produced the primary fixture below. */
const MODEL = `class Garage {
  sm {
    idle {
      open -> working.lifting;
    }
    working {
      lifting {
        done -> idle;
      }
    }
  }
}
`

/** Generated by `java -jar jars/umplesync.jar -generate EventSequence` from MODEL.
 *  The <h2>, grid, list and `p` region below is that output byte for byte, so the
 *  data-transition / data-parent metadata and the DOM structure are the real thing.
 *  The jar's <style> and trailing layout <script> are reduced here to the rules that
 *  affect hit testing -- the absolutely positioned floating column and the shifted
 *  body table -- so clicks are still tested against that overlapping layout.
 */
const EVENT_SEQUENCE_HTML = `<style>
  .event-sequence-grid, .event-sequence-list { font-size: 14px; }
  .event-sequence-grid .content-cell { text-align: center; min-width: 25px; }
  .event-sequence-grid .row-header { white-space: nowrap; }
  .event-sequence-grid .column-header > div { width: 25px; }
  .event-sequence-grid .column-header span {
    transform-origin: bottom left;
    transform: translateX(12px) rotate(-45deg);
    display: inline-block;
    white-space: nowrap;
  }
  .event-sequence-grid .wrapper { position: relative; }
  .event-sequence-grid .floating-col { position: absolute; z-index: 1; }
  .event-sequence-grid .inner-wrapper { position: relative; }
  .event-sequence-grid .table-body { overflow-x: auto; }
  .event-sequence-grid .table-body table { position: relative; }
  .event-sequence-grid .floating-col td { background-color: white; }
</style>

<h2>Class Garage state machine sm</h2>

<div class="event-sequence-grid">
  <div id="wrapper0" class="wrapper">
    <div class="floating-col">
      <table>
        <tr>
          <td class="row-header first">States</td>
        </tr>
        <tr>
          <td class="row-header" data-parent="">idle</td>
        </tr>
        <tr>
          <td class="row-header" data-parent="">working</td>
        </tr>
        <tr>
          <td class="row-header" data-parent="1">- lifting</td>
        </tr>
      </table>
    </div>
    <div class="table-body">
      <div class="inner-wrapper">
        <table>
          <tr>
            <td class="column-header"><div><span>START</span></div></td>
            <td class="column-header" data-transition="Garage*^*sm*^*open*^*idle*^*working.lifting*^*"><div><span>1. open</span></div></td>
          </tr>
          <tr>
            <td class="content-cell" data-parent="">X</td>
            <td class="content-cell">&nbsp;</td>
          </tr>
          <tr>
            <td class="content-cell" data-parent="">&nbsp;</td>
            <td class="content-cell">&nbsp;</td>
          </tr>
          <tr>
            <td class="content-cell" data-parent="1">&nbsp;</td>
            <td class="content-cell">X</td>
          </tr>
        </table>
      </div>
    </div>
  </div>
</div>

<table class="event-sequence-list">
  <tr>
    <td class="column-header">Event<br>Number</td>
    <td class="column-header">Event</td>
    <td class="column-header">Next State</td>
  </tr>
  <tr>
    <td class="">START</td>
    <td class="">-</td>
    <td class="">idle</td>
  </tr>
  <tr>
    <td class="">1</td>
    <td class="" data-transition="Garage*^*sm*^*open*^*idle*^*working.lifting*^*">open</td>
    <td class="">working.lifting</td>
  </tr>
</table>

<p>Event sequence ending reason: Visited all states</p>

<script>
  var wrapper = document.getElementById("wrapper0");
  var floatingCol = wrapper.getElementsByClassName('floating-col')[0];
  var innerWrapper = wrapper.getElementsByClassName("inner-wrapper")[0];
  var actualTable = innerWrapper.getElementsByTagName('table')[0];
  var spacerHeight = 40;
  actualTable.style.top = spacerHeight + 'px';
  floatingCol.style.top = spacerHeight - 1 + 'px';
  actualTable.style.left = floatingCol.offsetWidth - 6 + 'px';
</script>
`

/** Same class with the superstate declared first, so the initial state is nested. */
const NESTED_START_MODEL = `class Garage {
  sm {
    working {
      lifting {
        done -> idle;
      }
    }
    idle {
      open -> working.lifting;
    }
  }
}
`

/** The heading and event list from that model's generated output, byte for byte.
 *  The START row's Next State is the resolved initial state, `working.lifting`.
 *  Only the list is needed here, so the grid is left out.
 */
const NESTED_START_HTML = `<h2>Class Garage state machine sm</h2>

<table class="event-sequence-list">
  <tr>
    <td class="column-header">Event<br>Number</td>
    <td class="column-header">Event</td>
    <td class="column-header">Next State</td>
  </tr>
  <tr>
    <td class="">START</td>
    <td class="">-</td>
    <td class="">working.lifting</td>
  </tr>
  <tr>
    <td class="">1</td>
    <td class="" data-transition="Garage*^*sm*^*done*^*working.lifting*^*idle*^*">done</td>
    <td class="">idle</td>
  </tr>
</table>
`

function seedSession(page: Page) {
  return page.addInitScript(() => {
    localStorage.setItem(
      'umple-preferences-v1',
      JSON.stringify({ state: { hasSeenWelcome: true, dynamicGeneration: true }, version: 4 }),
    )
    sessionStorage.setItem(
      'umple-session-v1',
      JSON.stringify({
        state: { viewMode: 'eventSequence', generateTargetId: 'EventSequence' },
        version: 2,
      }),
    )
  })
}

async function installRoutes(page: Page, html: string) {
  await page.route('**/api/examples', (route) => route.fulfill({ json: [] }))

  const respond = (route: Route) =>
    route.fulfill({
      json: {
        modelId: 'playwright-model',
        result: JSON.stringify({ umpleClasses: [], umpleAssociations: [] }),
        html,
      },
    })

  await page.route('**/api/generate', respond)
  await page.route('**/api/diagram', respond)
}

/** Pastes rather than types: CodeMirror's auto-indent and bracket closing would
 *  otherwise rewrite the multi-line model as it is keyed in.
 */
async function pasteEditorCode(page: Page, code: string) {
  const content = page.locator('.cm-content').first()
  await content.click()
  await page.keyboard.press('Control+a')
  await content.evaluate((element, text) => {
    const data = new DataTransfer()
    data.setData('text/plain', text)
    element.dispatchEvent(new ClipboardEvent('paste', { clipboardData: data, bubbles: true, cancelable: true }))
  }, code)
  // Confirm the paste landed verbatim rather than being reindented or bracket-completed.
  const probe = code.split('\n').map((line) => line.trim()).find((line) => line.includes('->'))
  await expect(content).toContainText(probe ?? '')
}

interface EventSequenceFixture {
  model?: string
  html?: string
  /** Selector that must be present in the frame before the test clicks. */
  ready?: string
}

/** CodeMirror only mirrors its state selection into the DOM while the content is
 *  focused, and clicking inside the iframe moves focus there. Refocusing makes the
 *  selection readable without altering it, but the mirroring lands a tick later, so
 *  the read is polled.
 */
function expectSelectedEditorText(page: Page) {
  return expect.poll(
    async () => {
      await page.locator('.cm-content').first().evaluate((element) => (element as HTMLElement).focus())
      return page.evaluate(() => window.getSelection()?.toString() ?? '')
    },
    { timeout: 5_000 },
  )
}

async function openEventSequence(page: Page, fixture: EventSequenceFixture = {}) {
  const {
    model = MODEL,
    html = EVENT_SEQUENCE_HTML,
    ready = '.event-sequence-grid',
  } = fixture

  await seedSession(page)
  await installRoutes(page, html)
  await page.goto('/')
  await expect(page.getByTestId('app-shell')).toBeVisible()
  await pasteEditorCode(page, model)

  const iframe = page.getByTestId('html-diagram-iframe')
  await expect(iframe).toBeVisible({ timeout: 15_000 })
  const frame = page.frameLocator('[data-testid="html-diagram-iframe"]')
  await expect(frame.locator(ready)).toBeVisible()
  return frame
}

test.describe('Event Sequence source selection', () => {
  test('clicking a top-level state row selects its state block', async ({ page }) => {
    const frame = await openEventSequence(page)

    await frame.locator('.floating-col td', { hasText: /^idle$/ }).click()

    await expectSelectedEditorText(page).toBe(
      ['    idle {', '      open -> working.lifting;', '    }'].join('\n'),
    )
  })

  test('clicking a superstate row selects the whole superstate block', async ({ page }) => {
    const frame = await openEventSequence(page)

    await frame.locator('.floating-col td', { hasText: /^working$/ }).click()

    await expectSelectedEditorText(page).toBe(
      [
        '    working {',
        '      lifting {',
        '        done -> idle;',
        '      }',
        '    }',
      ].join('\n'),
    )
  })

  test('clicking a nested state row resolves its dotted path', async ({ page }) => {
    const frame = await openEventSequence(page)

    await frame.locator('.floating-col td', { hasText: /^- lifting$/ }).click()

    await expectSelectedEditorText(page).toBe(
      ['      lifting {', '        done -> idle;', '      }'].join('\n'),
    )
  })

  test('clicking a Next State cell selects the destination state', async ({ page }) => {
    const frame = await openEventSequence(page)

    await frame.locator('.event-sequence-list td', { hasText: /^working\.lifting$/ }).click()

    await expectSelectedEditorText(page).toBe(
      ['      lifting {', '        done -> idle;', '      }'].join('\n'),
    )
  })

  test('clicking an event column header selects the transition line', async ({ page }) => {
    const frame = await openEventSequence(page)

    await frame.locator('.column-header[data-transition]').click()

    await expectSelectedEditorText(page).toBe('      open -> working.lifting;')
  })

  test('clicking an event cell in the list selects the transition line', async ({ page }) => {
    const frame = await openEventSequence(page)

    await frame.locator('.event-sequence-list td[data-transition]').click()

    await expectSelectedEditorText(page).toBe('      open -> working.lifting;')
  })

  test("clicking the START row's Next State cell selects the initial state", async ({ page }) => {
    const frame = await openEventSequence(page)

    await frame.locator('.event-sequence-list tr').nth(1).locator('td').nth(2).click()

    await expectSelectedEditorText(page).toBe(
      ['    idle {', '      open -> working.lifting;', '    }'].join('\n'),
    )
  })

  test("resolves a nested initial state from the START row", async ({ page }) => {
    const frame = await openEventSequence(page, {
      model: NESTED_START_MODEL,
      html: NESTED_START_HTML,
      ready: '.event-sequence-list',
    })

    await frame.locator('.event-sequence-list tr').nth(1).locator('td').nth(2).click()

    await expectSelectedEditorText(page).toBe(
      ['      lifting {', '        done -> idle;', '      }'].join('\n'),
    )
  })

  test('noninteractive cells leave the editor selection untouched', async ({ page }) => {
    const frame = await openEventSequence(page)

    // Establish a known selection, then confirm inert cells never replace it.
    await frame.locator('.floating-col td', { hasText: /^idle$/ }).click()
    const baseline = ['    idle {', '      open -> working.lifting;', '    }'].join('\n')
    await expectSelectedEditorText(page).toBe(baseline)

    const inert = [
      frame.locator('.floating-col td.first'),
      frame.locator('.column-header', { hasText: /^START$/ }),
      frame.locator('.event-sequence-list td.column-header', { hasText: /^Next State$/ }),
      // The START row's event cell ("-") names no event. Its Next State cell is the
      // initial state and is covered by its own test.
      frame.locator('.event-sequence-list tr').nth(1).locator('td').nth(1),
      // Event Number cells name no state either.
      frame.locator('.event-sequence-list tr').nth(2).locator('td').nth(0),
      // A grid body cell, taken from the second column so the absolutely
      // positioned floating column does not cover it.
      frame.locator('.event-sequence-grid tr').last().locator('.content-cell').nth(1),
      frame.locator('p', { hasText: 'Event sequence ending reason' }),
    ]

    for (const target of inert) {
      await target.click()
      await expectSelectedEditorText(page).toBe(baseline)
    }
  })
})
